const displayColumnNames = [
    "Name",
    "Website",
    "Phone",
    "Owner",
    "City",
    "Email"
];

const displayColumnOptions = {
    valueKey: {
        "Owner": "ownerName",
        "City": "addressCity"
    }
};

return {
    columnNames: displayColumnNames,
    options: displayColumnOptions
}

// 1. Destructure the parameters from the single options object.
const { page, limit, query } = options;

// 2. Get context-specific properties from the service instance.
const entity = this.entity;
const columnConfig = this.getDisplayColumnConfig();
const entityAction = this.utilityService.buildEntityAction(entity, "SelectAll");

// 3. Use try...catch for robust error handling.
try {
    // Await the result from the cache service and return it.
    return await this.entityCacheService.getAll(
        entityAction,
        entity,
        page,
        limit,
        columnConfig,
        query
    );
} catch (error) {
    console.error(`Failed to get events for entity '${entity}':`, error);
    // Re-throw the error so the calling function knows the operation failed
    // and can display a message to the user.
    throw error;
}

try {
    // Construct the query specific to event logs
    const query = `documentTypeId=${entityType}&externalId=${entityId}`;
    const options = {
        query: query
    };

    const apiResponse = await this.dataService.getData(
        this.entity,
        options
    );

    if (apiResponse && Array.isArray(apiResponse.trackerDocuments)) {
        return apiResponse.trackerDocuments;
    } else {
        console.warn("Event logs API response missing 'trackerDocuments' array or format unexpected:", apiResponse);
        return [];
    }

} catch (error) {
    console.error("Error loading entity event logs:", error);
    this.utilityService.toast("Failed to load event logs.", "ERROR");
    throw error;
}

try {
    const trackerDocuments = await this.getAllEventsByEntityByEntityId(entityType, entityId);
    const allStates = trackerDocuments.flatMap(doc => doc.states || []);

    const formattedEntityType = this.getUppercasedEntityType(entityType);
    const allEvents = allStates
        .map(state => this.formatStateSummary(state, formattedEntityType))
        .reverse();

    return allEvents;
} catch (error) {
    console.error("Error loading activity events:", error);
    throw error;
}

