if (!trackerDocument) return;

const stateName = trackerDocument.stateName;
const modifiedDate = trackerDocument.timeReceived;

let performer = "-";
if (trackerDocument.states && trackerDocument.states.length > 0) {
    const lastState = trackerDocument.states.at(-1);
    performer = lastState.performer;
}

let actionPhrase = "Unknown Action";
if (stateName) {
    actionPhrase = `${stateName} ${entityType}`;
}

return {
    action: actionPhrase,
    performer: performer,
    modifiedOn: modifiedDate
};

if (!stateObj) return null;

const modifiedDate = stateObj.timeReceived;
const performer = stateObj.performer || "System";
let rawAction = stateObj.stateName || "Unknown Action";

rawAction = rawAction.replace("Event logged: ", "");
rawAction = rawAction.replace(/_/g, " ");
rawAction = rawAction.replace(/\b\w/g, char => char.toUpperCase());

const actionPhrase = `${rawAction}`;

return {
    action: actionPhrase,
    performer: performer,
    modifiedOn: modifiedDate,
    raw: stateObj
};

let entityUrl = this.entity;
if (activityType && entityType && entityId) entityUrl = `activity/${activityType}/${entityType}/${entityId}`;

return this.entityCacheService.getCachedEntityValue(entityUrl, "entities");

const prefix = "activity_";
let processedType = entityType;

if (processedType.startsWith(prefix) && processedType.length > prefix.length) {
    processedType = processedType.substring(prefix.length);
}

if (processedType.length > 0) {
    return processedType.charAt(0).toUpperCase() + processedType.slice(1);
}

return "";
